SELECT id, article_cover, article_title, create_time, type, is_top FROM tb_article WHERE is_delete = 0 AND status = 1
AND (create_time < #{cursorTime} OR (create_time = #{cursorTime} AND id < #{cursorId}))
ORDER BY create_time DESC, id DESC LIMIT #{limit}

SELECT id, article_title, create_time FROM tb_article WHERE is_delete = 0 AND status = 1
AND (create_time < #{cursorTime} OR (create_time = #{cursorTime} AND id < #{cursorId}))
ORDER BY create_time DESC, id DESC LIMIT #{limit}

